-- Production persistence schema (PostgreSQL-compatible)
CREATE TABLE users (id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'contributor', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE verification_cases (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), headline TEXT NOT NULL, article_text TEXT NOT NULL, source_url TEXT, publication TEXT, publication_date DATE, priority TEXT, status TEXT NOT NULL DEFAULT 'unreviewed', archived BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE claims (id UUID PRIMARY KEY, case_id UUID REFERENCES verification_cases(id) ON DELETE CASCADE, text TEXT NOT NULL, claim_type TEXT, priority TEXT, ai_analysis JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE evidence_notes (id UUID PRIMARY KEY, case_id UUID REFERENCES verification_cases(id) ON DELETE CASCADE, author_id UUID REFERENCES users(id), position TEXT NOT NULL, source TEXT NOT NULL, note TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE ai_analyses (id UUID PRIMARY KEY, case_id UUID UNIQUE REFERENCES verification_cases(id) ON DELETE CASCADE, summary TEXT, uncertainty TEXT, questions JSONB, evidence_gaps JSONB, checklist JSONB, loaded_language JSONB, created_at TIMESTAMPTZ DEFAULT now());
